short<-fread(out('03_marker_review/all_shortlists.tsv'));sig<-fread(file.path(old,'01_signatures/top50_signatures.tsv'));sg<-sig[MP%in%c('EpiMP07','EpiMP10'),.(set=if(uniqueN(MP)==2)'shared_MP07_MP10' else if(MP[1]=='EpiMP10')'MP10_unique' else 'MP07_unique'),by=.(gene_id=gene)];wt(sg,'03_marker_review/MP07_MP10_gene_partition.tsv');stopifnot(identical(sort(sg[,.N,by=set]$N),c(12L,38L,38L)))
genes<-sort(unique(c(short$gene_id,sg$gene_id)));alle<-list();pair<-list();diagnostic<-list()
