# No new DE: compare expression against other original clusters at the same resolution.
spec<-list()
for(i in seq_len(nrow(short))) {s<-short[i];cp<-comparisons[comparison==s$comparison];target<-if(s$orientation=='Right')cp$right else cp$left;if(target=='rest')next;d<-clsum[scope=='ALL' & resolution==cp$resolution & gene_id==s$gene_id];t<-d[cluster==target];others<-d[cluster!=target];top<-others[which.max(mean_expression)];closest<-others[which.min(abs(mean_expression-t$mean_expression))];spec[[i]]<-data.table(comparison=s$comparison,gene_id=s$gene_id,target=target,resolution=cp$resolution,target_expression=t$mean_expression,target_detection=t$mean_detection,n_target_samples=t$n_samples,highest_other_cluster=top$cluster,highest_other_expression=top$mean_expression,closest_other_cluster=closest$cluster,closest_other_expression=closest$mean_expression,n_other_clusters_equal_or_higher=sum(others$mean_expression>=t$mean_expression))}
wt(rbindlist(spec),'03_marker_review/shortlist_alternative_cluster_specificity.tsv')
for(i in 1:nrow(comparisons)) {cp<-comparisons[i];a<-qread(out(paste0('02_pseudobulk_markers/',cp$comparison,'_pseudobulk.qs')));samples<-unique(a$meta$sample);li<-match(paste(samples,'Left',sep='::'),a$meta$column_id);ri<-match(paste(samples,'Right',sep='::'),a$meta$column_id);ix<-match(genes,rownames(a$counts));base<-fread(out('00_audit/comparison_eligibility.tsv'))[comparison==cp$comparison];one<-rbindlist(lapply(seq_along(samples),function(j)data.table(sample=samples[j],gene_id=genes,expr_left=if(!is.na(li[j]))a$expression[ix,li[j]] else NA_real_,expr_right=if(!is.na(ri[j]))a$expression[ix,ri[j]] else NA_real_,pct_left=if(!is.na(li[j]))a$detection[ix,li[j]] else NA_real_,pct_right=if(!is.na(ri[j]))a$detection[ix,ri[j]] else NA_real_)));one<-merge(one,base,by='sample',all.x=TRUE);one[,`:=`(delta_expression=expr_left-expr_right,delta_detection=pct_left-pct_right)];pair[[i]]<-one
}
pa<-rbindlist(pair);wt(pa,'03_marker_review/shortlist_diagnostic_sample_contrasts.tsv.gz');dg<-merge(pa,sg,by='gene_id');wt(dg,'03_marker_review/MP07_MP10_per_gene_sample_contrasts.tsv.gz')
dgsummary<-rbindlist(lapply(c('ALL',sort(unique(dg$dataset))),function(ds){d<-if(ds=='ALL')dg else dg[dataset==ds];d[eligible==TRUE,.(n_samples=.N,expr_left=mean(expr_left),expr_right=mean(expr_right),pct_left=mean(pct_left),pct_right=mean(pct_right),delta_mean=mean(delta_expression),delta_median=median(delta_expression),positive_fraction=mean(delta_expression>0),negative_fraction=mean(delta_expression<0)),by=.(comparison,gene_id,set)][,scope:=ds]}));wt(dgsummary,'03_marker_review/MP07_MP10_per_gene_summary.tsv')
